import{_ as n,I as t,o as r,c as d,b6 as i,j as o,J as e,w as h}from"./chunks/framework.COUcLbTA.js";const P=JSON.parse('{"title":"Go 交通数据分析平台开发实战","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/stage-2/assignments/traffic-data-visualization-go/index.md","filePath":"zh-cn/stage-2/assignments/traffic-data-visualization-go/index.md"}'),p={name:"zh-cn/stage-2/assignments/traffic-data-visualization-go/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,f,m){const l=t("StepBar"),s=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="go-交通数据分析平台开发实战" tabindex="-1">Go 交通数据分析平台开发实战 <a class="header-anchor" href="#go-交通数据分析平台开发实战" aria-label="Permalink to “Go 交通数据分析平台开发实战”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本实战项目要求你围绕一份真实的 PRD，使用 Go 完成一个交通数据分析平台。这个项目的方向与前面的增删改查系统不同——你需要构建一条&quot;数据接入 → 聚合 → 告警 → 可视化&quot;的完整数据链路。这种数据产品在 IoT、监控、运营分析等场景中非常常见。</p><p>这是 Stage 2 的综合实战环节，也是你第一次接触 Go 语言。不用担心，有了前面 JavaScript / TypeScript 的基础，学习 Go 并不难——重点是理解数据链路的设计思路。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to “前置知识”">​</a></h2><p>在开始本项目之前，你应该已经掌握以下内容：</p><ul><li>前端页面设计与组件库使用（<a href="./../../frontend/ui-design/">UI 设计</a>、<a href="./../../frontend/modern-component-library/">现代组件库</a>）</li><li>后端接口设计与开发（<a href="./../../backend/ai-interface-code/">接口代码编写</a>）</li><li>数据库基础与 Supabase（<a href="./../../backend/database-supabase/">从数据库到 Supabase</a>）</li><li>Git 工作流与部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 应用</a>）</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to “学习目标”">​</a></h2><p>完成本实战后，你将能够：</p><ol><li>阅读 PRD 并提取数据产品的开发任务清单</li><li>使用 Go（Gin 或 Fiber）搭建后端 API 服务</li><li>设计数据接入、窗口聚合和告警的完整链路</li><li>让后端数据和前端看板保持一致</li><li>完成端到端联调，交付可演示的数据产品原型</li></ol><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to “项目简介”">​</a></h2><p>你要构建的产品是一个 Go 交通数据分析平台：</p><table tabindex="0"><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td><strong>数据接入</strong></td><td>接收原始交通事件并入库</td></tr><tr><td><strong>数据聚合</strong></td><td>按时间窗口计算趋势和拥堵指标</td></tr><tr><td><strong>告警</strong></td><td>基于规则生成告警记录</td></tr><tr><td><strong>看板展示</strong></td><td>在前端展示趋势图、排行榜和告警列表</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本项目的需求文档在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/traffic-data-visualization-go/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',14)),o("div",c,[e(s,null,{default:h(()=>[e(l,{active:0,items:[{title:"需求分析",description:"阅读 PRD，明确数据来源、指标口径和告警规则"},{title:"搭建骨架",description:"用 AI 生成 Go API 服务和前端看板骨架"},{title:"迭代开发",description:"补充聚合逻辑、告警规则和看板接口"},{title:"联调上线",description:"端到端跑通，部署并准备演示"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-阅读-prd" tabindex="-1">1.1 阅读 PRD <a class="header-anchor" href="#_1-1-阅读-prd" aria-label="Permalink to “1.1 阅读 PRD”">​</a></h3><p>打开 PRD 文档，重点回答以下问题：</p><ul><li>数据来源是什么？字段有哪些？</li><li>核心指标的定义是什么？（比如&quot;拥堵&quot;的具体标准）</li><li>告警规则是什么？第一版是否先收敛到简单规则？</li><li>看板包含哪些页面和图表？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上问题没有明确答案，不要开始写代码。需求理解不清楚是导致返工的最常见原因。</p></div><h3 id="_1-2-确认数据链路" tabindex="-1">1.2 确认数据链路 <a class="header-anchor" href="#_1-2-确认数据链路" aria-label="Permalink to “1.2 确认数据链路”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; ingest[&quot;数据接入 API&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ingest --&gt; raw[&quot;原始数据表&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  raw --&gt; agg[&quot;聚合任务&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agg --&gt; alert[&quot;告警规则&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agg --&gt; dashboard[&quot;看板接口&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  alert --&gt; dashboard</span></span></code></pre></div><h2 id="第二部分-搭建项目骨架" tabindex="-1">第二部分：搭建项目骨架 <a class="header-anchor" href="#第二部分-搭建项目骨架" aria-label="Permalink to “第二部分：搭建项目骨架”">​</a></h2><h3 id="_2-1-生成-go-api-服务" tabindex="-1">2.1 生成 Go API 服务 <a class="header-anchor" href="#_2-1-生成-go-api-服务" aria-label="Permalink to “2.1 生成 Go API 服务”">​</a></h3><p>提示词参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请基于当前 PRD，帮我生成一个 Go 交通数据分析平台骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 使用 Gin 或 Fiber</span></span>
<span class="line"><span>2. 提供数据接入接口</span></span>
<span class="line"><span>3. 提供聚合任务骨架</span></span>
<span class="line"><span>4. 提供 dashboard 和 alerts 接口骨架</span></span>
<span class="line"><span>5. 先不做真实复杂分析，只做可运行结构</span></span></code></pre></div><h3 id="_2-2-验证项目结构" tabindex="-1">2.2 验证项目结构 <a class="header-anchor" href="#_2-2-验证项目结构" aria-label="Permalink to “2.2 验证项目结构”">​</a></h3><p>逐项检查：</p><ul><li>[ ] Go 服务可以正常启动</li><li>[ ] 数据接入接口可接收并存储数据</li><li>[ ] 聚合任务框架已搭好</li><li>[ ] 前端看板页面可展示基本图表</li></ul><h2 id="第三部分-迭代开发" tabindex="-1">第三部分：迭代开发 <a class="header-anchor" href="#第三部分-迭代开发" aria-label="Permalink to “第三部分：迭代开发”">​</a></h2><h3 id="_3-1-按模块推进" tabindex="-1">3.1 按模块推进 <a class="header-anchor" href="#_3-1-按模块推进" aria-label="Permalink to “3.1 按模块推进”">​</a></h3><ol><li><strong>数据接入 API</strong>：接收原始交通事件，写入数据库</li><li><strong>数据聚合</strong>：按时间窗口聚合，计算趋势和拥堵指标</li><li><strong>告警规则</strong>：基于阈值生成告警记录</li><li><strong>看板接口</strong>：提供趋势数据、排行数据、告警列表</li><li><strong>前端看板</strong>：趋势图、排行榜、告警列表页面</li></ol><h3 id="_3-2-模块自检" tabindex="-1">3.2 模块自检 <a class="header-anchor" href="#_3-2-模块自检" aria-label="Permalink to “3.2 模块自检”">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>验证方法</th></tr></thead><tbody><tr><td>数据接入</td><td>原始数据是否正确入库</td></tr><tr><td>聚合口径</td><td>趋势、排名指标的计算逻辑是否一致</td></tr><tr><td>告警规则</td><td>告警触发条件是否符合预期</td></tr><tr><td>数据一致性</td><td>看板展示和后端数据是否对得上</td></tr><tr><td>API 规范</td><td>是否有统一返回结构和错误处理</td></tr></tbody></table><h2 id="第四部分-联调与上线" tabindex="-1">第四部分：联调与上线 <a class="header-anchor" href="#第四部分-联调与上线" aria-label="Permalink to “第四部分：联调与上线”">​</a></h2><h3 id="_4-1-端到端测试" tabindex="-1">4.1 端到端测试 <a class="header-anchor" href="#_4-1-端到端测试" aria-label="Permalink to “4.1 端到端测试”">​</a></h3><p>至少验证以下场景：</p><ul><li>接入一批测试数据 → 聚合任务执行 → 看板展示更新</li><li>触发告警条件 → 告警记录生成 → 告警页面显示</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本项目后，你需要提交以下内容：</p><ul><li>[ ] 可访问的线上演示链接</li><li>[ ] 源码仓库链接（含 README）</li><li>[ ] PRD 文档</li><li>[ ] 核心页面截图（数据接入演示、趋势看板、告警列表）</li><li>[ ] 60 秒演示视频</li></ul><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to “评分标准”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>基本要求</th><th>进阶要求</th></tr></thead><tbody><tr><td>PRD 对齐</td><td>功能和数据结构基本符合 PRD</td><td>能清晰说明指标口径和聚合逻辑</td></tr><tr><td>数据链路</td><td>接入 → 聚合 → 告警 → 看板可跑通</td><td>聚合任务支持增量更新</td></tr><tr><td>分析能力</td><td>趋势、排行、告警三个模块可用</td><td>指标可配置、告警规则可自定义</td></tr><tr><td>前端展示</td><td>看板能展示基本图表</td><td>图表支持时间范围筛选</td></tr><tr><td>工程完整度</td><td>Go API、数据库、前端链路已接通</td><td>API 有统一错误处理和日志</td></tr></tbody></table><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 设计</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型辅助编写接口代码与接口文档</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a></li></ul>`,30))])}const x=n(p,[["render",b]]);export{P as __pageData,x as default};
